 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Expand by 2, retaining the input in the upper-left quadrant.
    # Companion quadrants follow a keyed deterministic pseudo-random stream;
    # derive the seed from the input to make the expansion repeatable.
    import random
    seed = sum((r * 31 + c * 17 + v) * (v + 1) for r, row in enumerate(grid) for c, v in enumerate(row))
    rng = random.Random(seed)
    out = [[0] * (2*w) for _ in range(2*h)]
    for r in range(h):
        for c in range(w):
            out[r][c] = grid[r][c]
    colors = sorted({v for row in grid for v in row})
    for r in range(2*h):
        for c in range(2*w):
            if r < h and c < w:
                continue
            out[r][c] = rng.choice(colors)
    return out
